function perimeter111(n){if(n===29)return `<svg style="display:block;width:100%;max-width:190px;height:auto;margin:.3em auto" viewBox="0 0 160 115" role="img" aria-label="아래쪽 왼쪽과 가운데, 위쪽 가운데와 오른쪽에 정사각형 네 개가 이어진 모양"><g fill="white" stroke="#191511" stroke-width="1.5"><rect x="15" y="55" width="40" height="40"/><rect x="55" y="55" width="40" height="40"/><rect x="55" y="15" width="40" height="40"/><rect x="95" y="15" width="40" height="40"/></g></svg>`;if(n===31)return `<svg style="display:block;width:100%;max-width:330px;height:auto;margin:.3em auto" viewBox="0 0 340 140" role="img" aria-label="직육면체의 세 면: 4cm 곱하기 3cm, 3cm 곱하기 5cm, 4cm 곱하기 5cm"><g fill="white" stroke="#191511" stroke-width="1.5"><rect x="35" y="35" width="64" height="48"/><rect x="140" y="35" width="48" height="80"/><rect x="238" y="35" width="64" height="80"/></g><g fill="#191511" font-size="14" text-anchor="middle"><text x="67" y="27">4cm</text><text x="18" y="63">3cm</text><text x="164" y="27">3cm</text><text x="123" y="79">5cm</text><text x="270" y="27">4cm</text><text x="221" y="79">5cm</text></g></svg>`;const labels=n===30?['3cm','3cm','3cm']:['7cm','3cm','5cm'];return `<svg style="display:block;width:100%;max-width:230px;height:auto;margin:.3em auto" viewBox="0 0 270 190" role="img" aria-label="${n===30?'한 변이 3cm인 정육면체':'가로 7cm, 깊이 3cm, 높이 5cm인 직육면체'}"><g fill="white" stroke="#191511" stroke-width="1.5" stroke-linejoin="round"><path d="M45 70 L95 35 H225 L175 70 Z"/><path d="M175 70 L225 35 V125 L175 160 Z"/><path d="M45 70 H175 V160 H45 Z"/><path d="M95 35 V125 H225 M95 125 L45 160" fill="none" stroke-dasharray="4 3"/></g><g fill="#191511" font-size="14" text-anchor="middle"><text x="110" y="182">${labels[0]}</text><text x="46" y="30">${labels[1]}</text><text x="247" y="83">${labels[2]}</text></g></svg>`;}
