 const base=n===62?260:140,w=n===62?43:50,d=n===62?20:25,h=n===62?43:50,gy=80;
 const xy=(x,y)=>[base+x*w-y*d,gy+y*d],center=(x,y)=>{const [a,b]=xy(x,y);return [a+(w-d)/2,b+d/2]};
