 const grid=n===62?path:Array.from({length:16},(_,i)=>[i%4,Math.floor(i/4)]);
 const squares=grid.map(([x,y])=>{const [a,b]=xy(x,y);return `<path d="M${a} ${b} h${w} l-${d} ${d} h-${w} Z" fill="${n===62?'#eee':'#fff'}" stroke="#191511" stroke-width="1.1"/>`;}).join('');
 const centers=[[0,0],...path].map(([x,y])=>center(x,y));const line=centers.map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join(' ');
 const [a,b]=xy(0,0),left=a-d,right=left+w,frontY=b+d;const cube=`<g stroke="#191511" stroke-width="1.4" stroke-linejoin="round"><path d="M${left} ${frontY-h} l${d} -${d} h${w} l-${d} ${d} Z" fill="#f5f5f5"/><path d="M${right} ${frontY-h} l${d} -${d} v${h} l-${d} ${d} Z" fill="#ddd"/><path d="M${left} ${frontY-h} h${w} v${h} h-${w} Z" fill="#eee"/>${n===62?`<g stroke="none" fill="#191511" text-anchor="middle" font-size="20"><text x="${a+w/2-d/2}" y="${frontY-h-d/2+6}">2</text><text x="${left+w/2}" y="${frontY-h/2+7}">3</text><text x="${right+d/2}" y="${frontY-h/2-d/2+7}">1</text></g>`:(()=>{const dot=(x,y)=>`<circle cx="${x}" cy="${y}" r="2.8" fill="#191511" stroke="none"/>`;let v='';for(const u of [0.22,0.5,0.78])for(const q of [0.25,0.72])v+=dot(left+w*u+d*q,frontY-h-d*q);for(const [u,q] of [[.2,.2],[.8,.2],[.5,.5],[.2,.8],[.8,.8]])v+=dot(left+w*u,frontY-h+h*q);for(const q of [.22,.5,.78])v+=dot(right+d*.5,frontY-h+h*q-d*.5);return v;})()}</g>`;
 const net=n===62?[[0,0,2],[0,1,3],[1,1,1],[2,1,4],[3,1,6],[2,2,5]].map(([x,y,v])=>`<rect x="${12+x*37}" y="${12+y*37}" width="37" height="37" fill="#eee" stroke="#191511" stroke-width="1.2"/><text x="${30.5+x*37}" y="${37+y*37}" text-anchor="middle" font-size="17">${v}</text>`).join(''):'';
